// Turn every workflow returned by the n8n API into a downloadable .json file.
// The file contents are the untouched workflow definition, so anything written
// here can be re-imported into n8n as-is.

// Read the date from Backup Settings instead of recomputing it here. The folder
// name is built from that same value, so a run that straddles midnight - or an
// instance whose timezone differs from the container's - can never stamp a file
// with a date that disagrees with the folder holding it.
const backupDate = $('Backup Settings').first().json.backupLabel;

const files = [];

for (const item of $input.all()) {
  const workflow = item.json;

  // Google Drive tolerates most characters, but these break sync clients
  // and anything that later mirrors the folder to a local disk.
  const safeName = String(workflow.name || 'untitled')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 90)
    .trim() || 'untitled';

  const fileName = `${safeName} [${workflow.id}].json`;
  const contents = JSON.stringify(workflow, null, 2);

  files.push({
    json: {
      fileName,
      workflowId: workflow.id,
      workflowName: workflow.name,
      active: workflow.active === true,
      updatedAt: workflow.updatedAt,
      backupDate,
      sizeBytes: Buffer.byteLength(contents, 'utf8'),
    },
    binary: {
      data: {
        data: Buffer.from(contents, 'utf8').toString('base64'),
        mimeType: 'application/json',
        fileName,
        fileExtension: 'json',
      },
    },
  });
}

return files;

// Close out the run with something worth reading in the executions list.

const uploaded = $input.all();
const prepared = $('Build Backup Files').all();
const folder = $('Create Dated Folder').first().json;
const backupDate = $('Backup Settings').first().json.backupLabel;

const bytesPrepared = prepared.reduce(
  (total, item) => total + (item.json.sizeBytes || 0),
  0,
);

return [
  {
    json: {
      backupDate,
      folderName: folder.name || `n8n-backup-${backupDate}`,
      folderId: folder.id,
      folderUrl: `https://drive.google.com/drive/folders/${folder.id}`,
      workflowsFound: prepared.length,
      filesUploaded: uploaded.length,
      uploadsFailed: prepared.length - uploaded.length,
      bytesPrepared,
    },
  },
];

// Reached only by the error output of the upload node, so every workflow that
// COULD be uploaded already has been - a single bad file no longer costs us the
// rest of the backup. Throwing here is deliberate: it keeps the execution red
// in the executions list, so a partial backup is never mistaken for a clean one.

const failures = $input.all().map((item) => {
  const error = item.json.error;
  return {
    workflow: item.json.workflowName || item.json.fileName || 'unknown workflow',
    reason: (error && error.message) || error || 'unknown error',
  };
});

if (failures.length === 0) {
  return [];
}

const detail = failures
  .map((failure) => `- ${failure.workflow}: ${failure.reason}`)
  .join('\n');

throw new Error(
  `${failures.length} workflow file(s) failed to upload:\n${detail}`,
);
